 test('checkout and verified payment are idempotent and ledger balances',async()=>{const q=await booking.quote(customer,input(11));const [a,b]=await Promise.all([booking.checkout(customer,q.id),booking.checkout(customer,q.id)]);expect(a.id).toBe(b.id);const e={id:randomUUID(),orderId:a.id,amountPaise:a.totalPaise,currency:'INR',provider:'test'};await Promise.all([booking.confirmPayment(e),booking.confirmPayment(e)]);const [r]=await db.query('SELECT count(*)::int AS count FROM payment_events WHERE order_id=$1',[a.id]);expect(r.count).toBe(1);const [sum]=await db.query('SELECT sum(e.amount_paise)::int AS total FROM ledger_entries e JOIN ledger_transactions t ON t.id=e.transaction_id WHERE t.order_id=$1',[a.id]);expect(sum.total).toBe(0);});
