 test('payment statements are private and include simulated refunds',async()=>{const x=await paid(80);await booking.cancel(customer,x.session.id,0);await drainDemoOutbox(repo);const privatePath=`/api/orders/${x.order.id}`;expect((await request(app).get(`${privatePath}/statement`).auth('demo:creator',{type:'bearer'})).status).toBe(404);const detail=await request(app).get(`${privatePath}/payment-record`).auth('demo:customer',{type:'bearer'});expect(detail.status).toBe(200);expect(detail.body.data.refunds[0].status).toBe('simulated_refunded');const response=await request(app).get(`${privatePath}/statement`).auth('demo:customer',{type:'bearer'});expect(response.status).toBe(200);const pdf=await PDFDocument.load(Buffer.from(response.body.data.base64,'base64'));expect(pdf.getTitle()).toContain('demo statement');expect(pdf.getPageCount()).toBe(1);const history=await request(app).get('/api/payment-records').auth('demo:customer',{type:'bearer'});expect(history.body.data.orders.find((o:{id:string})=>o.id===x.order.id).refund_paise).toBe(x.order.totalPaise);});
 test('first acceptance wins under concurrent requests',async()=>{const x=await paid(13);await db.query("UPDATE sessions SET input=jsonb_set(input,'{mode}','\"on_demand\"') WHERE id=$1",[x.session.id]);const offers=await dispatch.dispatch(x.role.id);expect(offers.length).toBe(3);const identities=await Promise.all(offers.slice(0,2).map(async o=>(await db.getRepository(CreatorEntity).findOneByOrFail({id:o.creatorId})).accountId));const results=await Promise.allSettled(offers.slice(0,2).map((o,i)=>dispatch.accept(identities[i]!,o.id)));expect(results.filter(r=>r.status==='fulfilled')).toHaveLength(1);expect(await db.getRepository(RoleEntity).countBy({sessionId:x.session.id,status:'assigned'})).toBe(1);});
