 async function running(days:number,lateMinutes=0){
   const x=await paid(days),c=await repo.creator(creatorAccount),svc=new SessionService(repo,true),clock=new Date(x.session.startAt.getTime()+lateMinutes*60000);
   await db.getRepository(RoleEntity).update(x.role.id,{creatorId:c.id,status:'assigned'});await db.getRepository(SessionEntity).update(x.session.id,{status:'assigned'});
   const post=(action:string,at=clock,extra:object={})=>svc.transition(c.accountId,x.role.id,{action,clientId:randomUUID(),deviceAt:at.toISOString(),location:{...x.session.input.venue,accuracy:5},identityProof:'demo-selfie',...extra},at);
   await post('trip',x.session.startAt);await post('check_in');await post('start');return {...x,c,clock,post};
 }
