 test('a customer dispute stops automatic completion and operations can reopen or resolve it',async()=>{
   const x=await running(168),timing=new SessionTimingService(repo),end=new Date(x.session.endAt),q=await timing.request(creatorAccount,x.role.id,{clientId:randomUUID(),location:{...x.session.input.venue,accuracy:5}},end);
   expect((await request(app).get('/api/ops/completion-requests').auth('demo:customer',{type:'bearer'})).status).toBe(403);expect((await request(app).post(`/api/completion-requests/${q.id}/decision`).auth('demo:creator2',{type:'bearer'}).send({action:'confirm'})).status).toBe(404);
   await timing.decide(customer,q.id,{action:'dispute',reason:'The shoot is not yet complete'},end);await timing.closeDue(new Date(end.getTime()+2*3600000));expect((await repo.session(x.session.id)).status).toBe('in_session');expect((await timing.queue()).find((r:{id:string})=>r.id===q.id).status).toBe('disputed');
   await timing.decide(opsId,q.id,{action:'continue',reason:'Customer and creator agreed to continue'},end,true);const next=await timing.request(creatorAccount,x.role.id,{clientId:randomUUID(),location:{...x.session.input.venue,accuracy:5}},new Date(end.getTime()+2*3600000));expect(next.id).not.toBe(q.id);
   await timing.decide(customer,next.id,{action:'confirm'},new Date(end.getTime()+2*3600000));expect((await repo.session(x.session.id)).status).toBe('session_completed');await timing.closeDue(new Date(end.getTime()+4*3600000));expect((await db.query('SELECT status FROM completion_requests WHERE id=$1',[next.id]))[0].status).toBe('confirmed');
 });
